// Minimal JavaScript mode for CodeMirror 5 (keywords / atoms / strings / comments / numbers).
// Provided locally so the editor keeps syntax highlighting after switching from Python to Node.js.
(function () {
  if (typeof CodeMirror === 'undefined') return;
  var KEYWORDS = {};
  ('break case catch class const continue debugger default delete do else export extends finally ' +
   'for function if import in instanceof let new return super switch this throw try typeof var void ' +
   'while with yield async await of static get set').split(' ').forEach(function (k) { KEYWORDS[k] = true; });
  var ATOMS = { 'true': 1, 'false': 1, 'null': 1, 'undefined': 1, 'NaN': 1, 'Infinity': 1 };
  var OPERATOR = /[+\-*&%=<>!?|~^:]/;

  function tokenBase(stream, state) {
    if (stream.eatSpace()) return null;
    var ch = stream.next();
    if (ch === '/') {
      if (stream.eat('*')) { state.tokenize = tokenComment; return state.tokenize(stream, state); }
      if (stream.eat('/')) { stream.skipToEnd(); return 'comment'; }
      if (stream.eatWhile(/[\w\\/]/)) return 'string-2';
      return null;
    }
    if (ch === '"' || ch === "'" || ch === '`') { state.quote = ch; state.tokenize = tokenString; return state.tokenize(stream, state); }
    if (/\d/.test(ch)) { stream.eatWhile(/[\w.]/); return 'number'; }
    if (/\w/.test(ch)) {
      stream.eatWhile(/\w/);
      var w = stream.current();
      if (KEYWORDS[w]) return 'keyword';
      if (ATOMS[w]) return 'atom';
      return 'variable';
    }
    if ('{}[]()'.indexOf(ch) >= 0) return 'bracket';
    if (OPERATOR.test(ch)) { stream.eatWhile(OPERATOR); return 'operator'; }
    return null;
  }
  function tokenString(stream, state) {
    var escaped = false, ch;
    while ((ch = stream.next()) != null) {
      if (ch === state.quote && !escaped) { state.tokenize = tokenBase; break; }
      escaped = (!escaped && ch === '\\');
    }
    return 'string';
  }
  function tokenComment(stream, state) {
    var ch, prev;
    while ((ch = stream.next()) != null) {
      if (ch === '/' && prev === '*') { state.tokenize = tokenBase; break; }
      prev = ch;
    }
    return 'comment';
  }

  CodeMirror.defineMode('javascript', function () {
    return {
      startState: function () { return { tokenize: tokenBase, quote: null }; },
      token: function (stream, state) { return state.tokenize(stream, state); }
    };
  });
  CodeMirror.defineMIME('text/javascript', 'javascript');
  CodeMirror.defineMIME('application/javascript', 'javascript');
})();
